WITH filtered AS (SELECT id, page, event_time, duration_sec, DATEDIFF(CURRENT_DATE(), event_time) / 365.25 AS years_since_event_time FROM web_events WHERE event_time >= TO_TIMESTAMP('2023-05-03 02:00:00') AND event_type NOT IN ('search', 'page_view')) SELECT id, page, ROW_NUMBER() OVER (PARTITION BY DATE_TRUNC('month', event_time), page ORDER BY event_time, id) AS seq_no, ROW_NUMBER() OVER (PARTITION BY MONTH(event_time), page ORDER BY duration_sec DESC, id) AS seq_no_2, STDDEV_SAMP(years_since_event_time) OVER (PARTITION BY page) AS page_stddev_samp_years_since_event_time, COUNT(years_since_event_time) OVER (ORDER BY CAST(event_time AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS years_since_event_time_count_7d FROM filtered WHERE event_time >= '2025-01-24'
